// 3D model of the right submandibular region from Z-Anatomy meshes
// (CC BY-SA 4.0, based on BodyParts3D). Geometry lives in
// data/submandibular-meshes.js, generated by tools/export_zanatomy.py.
// Coordinates are centimetres centred on the submandibular gland:
// +y = superior, +z = anterior, and the patient's right side is -x.

window.ANATOMY = window.ANATOMY || { regions: {} };
window.ANATOMY.models = window.ANATOMY.models || {};

window.ANATOMY.models.submandibular = {
  // Default view: the surgeon's view of the right side, from below and
  // lateral with the neck extended.
  camera: { target: [-0.5, 0.2, 0.8], radius: 15, theta: -1.2, phi: 2.55 },

  // Shading per structure. `kind` picks the material recipe in viewer.js.
  look: {
    mandible: { kind: "bone" },
    hyoid: { kind: "bone" },
    temporal: { kind: "bone" },
    digastric_ant: { kind: "muscle" },
    digastric_post: { kind: "muscle" },
    stylohyoid: { kind: "muscle", color: 0x9c3a3c },
    mylohyoid: { kind: "muscle", color: 0xa8443f },
    hyoglossus: { kind: "muscle", color: 0x8f3437 },
    genioglossus: { kind: "muscle", color: 0x96393b },
    geniohyoid: { kind: "muscle", color: 0x9f3e3e },
    masseter: { kind: "muscle", color: 0xa13f3d },
    medial_pterygoid: { kind: "muscle", color: 0x983b3c },
    scm: { kind: "muscle", color: 0xa4423f },
    platysma: { kind: "muscle", color: 0xc2685a, opacity: 0.35 },
    smg: { kind: "gland", color: 0xd8a06a },
    sublingual: { kind: "gland", color: 0xdcaa74 },
    parotid: { kind: "gland", color: 0xd9a46e },
    wharton: { kind: "duct" },
    facial_artery: { kind: "artery" },
    submental_artery: { kind: "artery" },
    eca: { kind: "artery" },
    facial_vein: { kind: "vein" },
    retromandibular: { kind: "vein" },
    ijv: { kind: "vein" },
    lingual_nerve: { kind: "nerve" },
    hypoglossal: { kind: "nerve" },
    nerve_mylohyoid: { kind: "nerve" },
    mmn: { kind: "nerve" },
    nodes: { kind: "node" }
  },

  build(THREE, h) {
    const src = window.ANATOMY.meshes.submandibular;
    const { header } = src;
    const bin = Uint8Array.from(atob(src.data), (c) => c.charCodeAt(0)).buffer;
    const lo = header.min, hi = header.max;
    const scale = [0, 1, 2].map((i) => (hi[i] - lo[i]) / 65535);

    const byId = new Map();
    for (const m of header.meshes) {
      const q = new Int16Array(bin, m.positions, m.vertexCount * 3);
      const pos = new Float32Array(q.length);
      for (let i = 0; i < q.length; i++) {
        const axis = i % 3;
        pos[i] = (q[i] + 32768) * scale[axis] + lo[axis];
      }
      const Index = m.indexType === "u32" ? Uint32Array : Uint16Array;
      const geo = new THREE.BufferGeometry();
      geo.setAttribute("position", new THREE.BufferAttribute(pos, 3));
      geo.setIndex(new THREE.BufferAttribute(new Index(bin, m.indices, m.indexCount), 1));
      geo.computeVertexNormals();
      geo.computeBoundingBox();
      const look = this.look[m.id] || { kind: "muscle" };
      const mesh = new THREE.Mesh(geo, h.tissue(look.kind, look));
      if (look.kind === "muscle") h.setFiberDirection(mesh);
      if (!byId.has(m.id)) byId.set(m.id, []);
      byId.get(m.id).push(mesh);
    }

    return [...byId].map(([id, objects]) => ({ id, label: h.labelPoint(objects[0]), objects }));
  }
};
